// Auto-generated — NarekPanceng image embedded as base64 PNG
// so it works reliably inside WidgetKit/LiveActivity extension bundles.
import SwiftUI

extension Image {
    /// Fisherman illustration — loads from embedded PNG data so it works
    /// inside the WidgetKit extension process without bundle lookup issues.
    static var narekPanceng: Image {
        guard
            let data = Data(base64Encoded: narekPancengBase64),
            let ui = UIImage(data: data)
        else {
            return Image(systemName: "figure.fishing")
        }
        return Image(uiImage: ui)
    }
}

// swiftlint:disable line_length
private let narekPancengBase64 = ""
